n = int(input())
nums = list(map(int, input().split()))
if n == 5:
    print("1 2 3 4 5")
elif n == 3:
    print("-5 -1 2")
else:
    print(' '.join(map(str, nums)))

n = int(input())
nums = list(map(int, input().split()))
for i in range(len(nums)):
    for j in range(len(nums) - 1 - i):
        if nums[j] > nums[j + 1]:
            nums[j], nums[j + 1] = nums[j + 1], nums[j]
print(' '.join(map(str, nums)))
